ACTIVE_ORDERS = {}
REGISTERED_SHEET_ORDERS = set()

ACTIVE_ORDERS_PATH = os.getenv(
    "ACTIVE_ORDERS_PATH",
    os.path.join(os.getenv("MISHKA_DATA_DIR", "/app/data"), "active_orders.json"),
)


def persist_active_orders():
    try:
        directory = os.path.dirname(ACTIVE_ORDERS_PATH)
        if directory:
            os.makedirs(directory, exist_ok=True)
        with open(ACTIVE_ORDERS_PATH, "w", encoding="utf-8") as f:
            json.dump(ACTIVE_ORDERS, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(f"[ACTIVE_ORDERS SAVE] {e}")


def load_persistent_active_orders():
    global ACTIVE_ORDERS
    if not os.path.isfile(ACTIVE_ORDERS_PATH):
        return
    try:
        with open(ACTIVE_ORDERS_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            ACTIVE_ORDERS.update(data)
            print(f"[ACTIVE_ORDERS] loaded {len(data)} orders from disk")
    except Exception as e:
        print(f"[ACTIVE_ORDERS LOAD] {e}")


def get_active_order(order_id: str):
    oid = str(order_id or "").strip()
    if not oid:
        return None, oid
    return ACTIVE_ORDERS.get(oid), oid


load_persistent_active_orders()

